// Trusted installed CIE Copilot hook generated by npm run git:hooks:install.
// The committed .githooks files are templates, not trusted enforcement.
// Runtime snapshot SHA256: ${runtimeSha256}
// Refresh from a trusted main/baseline checkout when hook logic changes.

const fs = require('node:fs');
const { createHash } = require('node:crypto');
const { pathToFileURL } = require('node:url');

const hookName = ${JSON.stringify(hookName)};
const runtimePath = ${JSON.stringify(runtimePath)};
const expectedSha256 = ${JSON.stringify(runtimeSha256)};

function formatError(error) {
  if (!error) return null;
  return error && error.stack ? error.stack : String(error);
}

function failClosed(message, error) {
  const lines = ['[git guardrails] ' + message];
  const details = formatError(error);
  if (details) lines.push(details);
  lines.push('[git guardrails] Reinstall trusted hooks from a trusted main/baseline checkout: npm run git:hooks:install');
  fs.writeSync(2, lines.join('\\n') + '\\n');
  process.exit(1);
}

let runtimeBytes;
try {
  runtimeBytes = fs.readFileSync(runtimePath);
} catch (error) {
  failClosed('trusted hook runtime is missing: ' + runtimePath, error);
}

